import sys


def main():
    lines = sys.stdin.read().splitlines()
    home = lines[0].split("=")[1].strip()
    for raw in lines[1:]:
        if not raw.strip():
            continue
        fields = [f.strip() for f in raw.split(";")]
        title, first, last, street, postcode, city, country = fields[:7]
        name_line = f"{title} {first} {last}".strip()
        if not first and not last:
            name_line = "To the occupant"
        print(name_line)
        if street.strip():
            print(street)
        if postcode.strip() and city.strip():
            print(f"{postcode} {city}")
        if country.strip() and country.upper() != home.upper():
            print(country.upper())
        if street.strip() and postcode.strip() and city.strip():
            print("---")


if __name__ == "__main__":
    main()
